<?php
require_once __DIR__ . '/includes/admin_header.php';
require_once __DIR__ . '/includes/admin_sidebar.php';

$db = get_db_connection();
$message = '';
$message_type = '';
$action = $_GET['action'] ?? 'list';
$edit_id = intval($_GET['id'] ?? 0);

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $degree=sanitize_input($_POST['degree']??''); $institution=sanitize_input($_POST['institution']??''); $field_of_study=sanitize_input($_POST['field_of_study']??'');
    $start_year=sanitize_input($_POST['start_year']??''); $end_year=sanitize_input($_POST['end_year']??''); $status=sanitize_input($_POST['status']??'Pursuing'); $grade_marks=sanitize_input($_POST['grade_marks']??''); $sort_order=intval($_POST['sort_order']??0);
    if($db){try{if($edit_id>0){$stmt=$db->prepare("UPDATE education SET degree = :deg, institution = :inst, field_of_study = :field, start_year = :sy, end_year = :ey, status = :st, grade_marks = :grd, sort_order = :sort WHERE id = :id");$stmt->execute([':deg'=>$degree,':inst'=>$institution,':field'=>$field_of_study,':sy'=>$start_year,':ey'=>$end_year,':st'=>$status,':grd'=>$grade_marks,':sort'=>$sort_order,':id'=>$edit_id]);$message="Education record updated!";$message_type="success";}else{$stmt=$db->prepare("INSERT INTO education (degree, institution, field_of_study, start_year, end_year, status, grade_marks, sort_order) VALUES (:deg, :inst, :field, :sy, :ey, :st, :grd, :sort)");$stmt->execute([':deg'=>$degree,':inst'=>$institution,':field'=>$field_of_study,':sy'=>$start_year,':ey'=>$end_year,':st'=>$status,':grd'=>$grade_marks,':sort'=>$sort_order]);$message="Education record added!";$message_type="success";}$action='list';}catch(Exception $e){$message="Database error: ".$e->getMessage();$message_type="danger";}}
}
if($action==='delete'&&$edit_id>0&&$db){try{$stmt=$db->prepare("DELETE FROM education WHERE id = :id");$stmt->execute([':id'=>$edit_id]);$message="Record deleted!";$message_type="success";}catch(Exception $e){}$action='list';}
$education=get_portfolio_education(); $edit_edu=null; if($action==='edit'&&$edit_id>0){foreach($education as $ed){if(isset($ed['id'])&&intval($ed['id'])===$edit_id){$edit_edu=$ed;break;}}}
?>
<main class="admin-main"><div class="admin-topbar"><div><h3 class="font-weight-bold mb-0">Education Qualifications</h3><small class="admin-text-muted">Manage Degrees, Colleges, Passing Years & Status</small></div><div><?php if($action==='list'): ?><a href="education.php?action=add" class="btn btn-info text-dark font-weight-bold"><i class="fas fa-plus me-1"></i> Add Degree / College</a><?php else: ?><a href="education.php" class="btn btn-outline-secondary"><i class="fas fa-arrow-left me-1"></i> Back to List</a><?php endif; ?></div></div>
<?php if(!empty($message)): ?><div class="alert alert-<?php echo $message_type; ?> alert-dismissible fade show" role="alert"><?php echo htmlspecialchars($message); ?><button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button></div><?php endif; ?>
<?php if($action==='add'||$action==='edit'): ?><div class="admin-card"><h5 class="font-weight-bold mb-4"><?php echo $action==='edit'?'Edit Education Record':'Add Education Record'; ?></h5><form method="POST" action="education.php<?php echo $action==='edit'?'?action=edit&id='.$edit_id:''; ?>"><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label small font-weight-bold">Degree / Certificate Name *</label><input type="text" name="degree" class="form-control" value="<?php echo htmlspecialchars($edit_edu['degree']??''); ?>" placeholder="Bachelor of Commerce (B.Com)" required></div><div class="col-md-6"><label class="form-label small font-weight-bold">College / Institution *</label><input type="text" name="institution" class="form-control" value="<?php echo htmlspecialchars($edit_edu['institution']??''); ?>" placeholder="Joypur Panchanan Roy College" required></div></div><div class="row g-3 mb-3"><div class="col-md-4"><label class="form-label small font-weight-bold">Field of Study</label><input type="text" name="field_of_study" class="form-control" value="<?php echo htmlspecialchars($edit_edu['field_of_study']??''); ?>" placeholder="Commerce / Computer Application"></div><div class="col-md-2"><label class="form-label small font-weight-bold">Start Year</label><input type="text" name="start_year" class="form-control" value="<?php echo htmlspecialchars($edit_edu['start_year']??''); ?>" placeholder="2023"></div><div class="col-md-2"><label class="form-label small font-weight-bold">End Year / Passing</label><input type="text" name="end_year" class="form-control" value="<?php echo htmlspecialchars($edit_edu['end_year']??''); ?>" placeholder="2026"></div><div class="col-md-2"><label class="form-label small font-weight-bold">Status *</label><select name="status" class="form-select"><option value="Pursuing" <?php echo ($edit_edu['status']??'')==='Pursuing'?'selected':''; ?>>Pursuing</option><option value="Completed" <?php echo ($edit_edu['status']??'')==='Completed'?'selected':''; ?>>Completed</option></select></div><div class="col-md-2"><label class="form-label small font-weight-bold">Grade / Marks</label><input type="text" name="grade_marks" class="form-control" value="<?php echo htmlspecialchars($edit_edu['grade_marks']??''); ?>" placeholder="First Division / Ongoing"></div></div><button type="submit" class="btn btn-info text-dark font-weight-bold px-4 py-2 mt-3"><i class="fas fa-save me-1"></i> Save Education</button></form></div><?php else: ?><div class="admin-card"><div class="table-responsive"><table class="table table-dark-custom align-middle mb-0"><thead><tr><th>Degree</th><th>College</th><th>Years</th><th>Status</th><th>Grade</th><th>Actions</th></tr></thead><tbody><?php foreach($education as $ed): ?><tr><td class="font-weight-bold admin-text-primary"><?php echo htmlspecialchars($ed['degree']); ?></td><td><span class="text-info font-weight-bold"><?php echo htmlspecialchars($ed['institution']); ?></span></td><td class="small admin-text-muted"><?php echo htmlspecialchars($ed['start_year']); ?> - <?php echo htmlspecialchars($ed['end_year']); ?></td><td><span class="badge bg-info text-dark"><?php echo htmlspecialchars($ed['status']); ?></span></td><td class="small text-success font-weight-bold"><?php echo htmlspecialchars($ed['grade_marks']??'N/A'); ?></td><td><?php if(isset($ed['id'])): ?><a href="education.php?action=edit&id=<?php echo $ed['id']; ?>" class="btn btn-sm btn-outline-info me-1"><i class="fas fa-edit"></i></a><a href="education.php?action=delete&id=<?php echo $ed['id']; ?>" class="btn btn-sm btn-outline-danger btn-delete-confirm"><i class="fas fa-trash"></i></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?></main>
<?php require_once __DIR__ . '/includes/admin_footer.php'; ?>
